package com.narratiaa.journal;

import com.narratiaa.auth.AuthService;import com.narratiaa.common.ApiException;import com.narratiaa.library.LibraryService;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.sql.*;import java.util.*;

@RestController @RequestMapping("/api/journal")
public class JournalController {
  private final AuthService auth;private final LibraryService lib;private final JdbcTemplate db;public JournalController(AuthService a,LibraryService l,JdbcTemplate d){auth=a;lib=l;db=d;}private long uid(HttpServletRequest r){return auth.requireUser(r).id();}
  private Map<String,Object> entry(ResultSet x)throws SQLException{var m=new LinkedHashMap<String,Object>();m.put("id",x.getLong(1));m.put("bookId",x.getLong(2));m.put("bookTitle",x.getString(3));m.put("type",x.getString(4));m.put("content",x.getString(5));m.put("pageNumber",x.getObject(6));m.put("tags",x.getString(7));m.put("createdAt",x.getObject(8));m.put("updatedAt",x.getObject(9));return m;}
  private Map<String,Object> get(long u,long id){var x=db.query("SELECT j.id,j.book_id,b.title,j.type,j.content,j.page_number,j.tags,j.created_at,j.updated_at FROM journal_entries j JOIN books b ON b.id=j.book_id WHERE j.user_id=? AND j.id=?",(r,n)->entry(r),u,id);return x.isEmpty()?null:x.getFirst();}
  @GetMapping Map<String,Object> all(HttpServletRequest r){return Map.of("entries",db.query("SELECT j.id,j.book_id,b.title,j.type,j.content,j.page_number,j.tags,j.created_at,j.updated_at FROM journal_entries j JOIN books b ON b.id=j.book_id WHERE j.user_id=? ORDER BY j.created_at DESC",(x,n)->entry(x),uid(r)));}
  @GetMapping("/{id}")Map<String,Object> one(HttpServletRequest r,@PathVariable long id){var e=get(uid(r),id);if(e==null)throw new ApiException(HttpStatus.NOT_FOUND,"Entry not found.");return Map.of("entry",e);}
  @PostMapping ResponseEntity<Map<String,Object>> create(HttpServletRequest r,@RequestBody Map<String,Object>b){long u=uid(r),book=number(b.get("bookId"));lib.requireBook(u,book);String content=Objects.toString(b.get("content"),"").trim();if(content.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Book and content are required.");Long id=db.queryForObject("INSERT INTO journal_entries(user_id,book_id,type,content,page_number,tags) VALUES(?,?,?,?,?,?) RETURNING id",Long.class,u,book,"quote".equals(b.get("type"))?"quote":"note",content,nullableNumber(b.get("pageNumber")),Objects.toString(b.get("tags"),""));return ResponseEntity.status(201).body(Map.of("id",id));}
  @PutMapping("/{id}")Map<String,Object> update(HttpServletRequest r,@PathVariable long id,@RequestBody Map<String,Object>b){long u=uid(r);var e=get(u,id);if(e==null)throw new ApiException(HttpStatus.NOT_FOUND,"Entry not found.");String c=Objects.toString(b.getOrDefault("content",e.get("content")),"").trim();if(c.isBlank())throw new ApiException(HttpStatus.BAD_REQUEST,"Content is required.");db.update("UPDATE journal_entries SET type=?,content=?,page_number=?,tags=?,updated_at=CURRENT_TIMESTAMP WHERE user_id=? AND id=?","quote".equals(b.getOrDefault("type",e.get("type")))?"quote":"note",c,b.containsKey("pageNumber")?nullableNumber(b.get("pageNumber")):e.get("pageNumber"),Objects.toString(b.getOrDefault("tags",e.get("tags")),""),u,id);return Map.of("entry",get(u,id));}
  @DeleteMapping("/{id}")Map<String,String> delete(HttpServletRequest r,@PathVariable long id){if(db.update("DELETE FROM journal_entries WHERE user_id=? AND id=?",uid(r),id)==0)throw new ApiException(HttpStatus.NOT_FOUND,"Entry not found.");return Map.of("message","Entry deleted.");}
  private long number(Object o){try{return Long.parseLong(String.valueOf(o));}catch(Exception e){throw new ApiException(HttpStatus.BAD_REQUEST,"Book and content are required.");}}private Integer nullableNumber(Object o){try{return o==null||String.valueOf(o).isBlank()?null:Integer.valueOf(String.valueOf(o));}catch(Exception e){return null;}}
}
